const node = (js: string) => `node -e "${js.replace(/"/g, '\\\\"')}"`;
const cmd = [
  'echo "===1 RECORDINGS COUNT==="',
  'curl -sS -m 15 http://127.0.0.1:8765/api/recordings | node -e "let s=\'\';process.stdin.on(\'data\',d=>s+=d).on(\'end\',()=>{const j=JSON.parse(s);console.log(\'count:\',j.recordings.length);console.log(\'first:\',j.recordings[0].id)})"',
  'echo "===2+3 LAB MODELS==="',
  'curl -sS -m 15 http://127.0.0.1:8765/api/lab/models > /tmp/lm.json 2>/dev/null; curl -sS -m 15 http://127.0.0.1:8765/api/lab/models | node -e "let s=\'\';process.stdin.on(\'data\',d=>s+=d).on(\'end\',()=>{const j=JSON.parse(s);const g1=j.g1_models,m=j.models;console.log(\'g1_count:\',g1.length,\'models_count:\',m.length);const n=[\'gate2v58_smooth_pidgate\',\'gate2v59_focal_warp\',\'gate2v60_phone_warp\',\'gate2v61_keyword_mix\',\'gate2v62_speechtrim\',\'gate2v63_pca_frontend\',\'gate2v64_paired_negatives\',\'gate2v64c_stochmel\',\'gate2v64d_expandedneg\',\'gate2v64p_paired_owner\',\'gate2v65_stoch15k\'];for(const x of n)console.log((m.includes(x)?\'PRESENT \':\'MISSING \')+x);console.log(\'last8:\',m.slice(-8).join(\',\'))})"',
  'echo "===5 HTML IDS==="',
  'curl -sS -m 15 http://127.0.0.1:8765/pipeline_all_in_one.html | node -e "let s=\'\';process.stdin.on(\'data\',d=>s+=d).on(\'end\',()=>{console.log(\'len:\',s.length);for(const x of [\'all-recframe-toggle\',\'rf-start\',\'rf-rec\',\'rf-label\',\'rf-results\',\'rf-refresh\'])console.log((s.includes(x)?\'PRESENT \':\'MISSING \')+x)})"'
